import{_ as c,C as i,o as g,c as p,j as t,a as o,E as a,a2 as s}from"./chunks/framework.1L7G9bmn.js";const x=JSON.parse('{"title":"Architecture Overview","description":"","frontmatter":{},"headers":[],"relativePath":"architecture/index.md","filePath":"architecture/index.md"}'),m={name:"architecture/index.md"};function h(u,e,y,v,f,S){const r=i("ArchitectureFlow"),n=i("TelemetrySimulator"),d=i("SchmittHysteresisDiagram"),l=i("BatterySequenceFlow");return g(),p("div",null,[e[0]||(e[0]=t("h1",{id:"architecture-overview",tabindex:"-1"},[o("Architecture Overview "),t("a",{class:"header-anchor",href:"#architecture-overview","aria-label":'Permalink to "Architecture Overview"'},"​")],-1)),e[1]||(e[1]=t("p",null,[o("The "),t("strong",null,"Veg Sahayyak SDK"),o(" is engineered around a clean, decoupled, and framework-agnostic architecture. This ensures high-accuracy telematics processing in background environments without imposing dependency injection frameworks (like Hilt or Koin) onto host applications.")],-1)),e[2]||(e[2]=t("hr",null,null,-1)),e[3]||(e[3]=t("h2",{id:"🏛️-modular-design",tabindex:"-1"},[o("🏛️ Modular Design "),t("a",{class:"header-anchor",href:"#🏛️-modular-design","aria-label":'Permalink to "🏛️ Modular Design"'},"​")],-1)),e[4]||(e[4]=t("p",null,"The SDK is strictly modularized into 5 components to enforce separation of concerns and enable flexible, lightweight B2B integration:",-1)),a(r),e[5]||(e[5]=s('<h3 id="module-responsibilities" tabindex="-1">Module Responsibilities <a class="header-anchor" href="#module-responsibilities" aria-label="Permalink to &quot;Module Responsibilities&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">Module</th><th style="text-align:left;">Namespace</th><th style="text-align:left;">Role</th></tr></thead><tbody><tr><td style="text-align:left;"><strong><code>speed-core</code></strong></td><td style="text-align:left;"><code>com.vegsahayyak.speedcore</code></td><td style="text-align:left;"><strong>Headless Engine</strong>: Location tracking, <code>TelematicsEngine</code> signal processing, Foreground Service, <code>SpeedColorScheme</code>, persistent preferences, and repository contracts. <strong>Crucially, this module is entirely headless and contains zero Jetpack Compose or UI dependencies.</strong></td></tr><tr><td style="text-align:left;"><strong><code>speed-ui</code></strong></td><td style="text-align:left;"><code>com.vegsahayyak.speedui</code></td><td style="text-align:left;"><strong>Jetpack Compose UI</strong>: Production-ready, animated <code>SpeedGauge</code> canvas component, <code>HudDisplay</code> night windshield projection, and <code>SpeedUiColorScheme</code>. All UI rendering is fully delegated here.</td></tr><tr><td style="text-align:left;"><strong><code>speed-overlay</code></strong></td><td style="text-align:left;"><code>com.vegsahayyak.speedoverlay</code></td><td style="text-align:left;"><strong>Floating PiP Overlay</strong>: Lightweight floating Picture-in-Picture window for persistent speed display over third-party navigation apps.</td></tr><tr><td style="text-align:left;"><strong><code>speed-autostart</code></strong></td><td style="text-align:left;"><code>com.vegsahayyak.speedautostart</code></td><td style="text-align:left;"><strong>Zero-Touch Autostart</strong>: Seamless background trip detection via Google Play Activity Recognition (<code>IN_VEHICLE</code> transitions).</td></tr><tr><td style="text-align:left;"><strong><code>speed-bom</code></strong></td><td style="text-align:left;"><code>com.vegsahayyak.speedbom</code></td><td style="text-align:left;"><strong>Bill of Materials</strong>: Aligns module versioning (v2.1.0) so clients never encounter runtime ABI mismatches.</td></tr></tbody></table><hr><h2 id="📐-signal-processing-telematics-engine" tabindex="-1">📐 Signal Processing &amp; Telematics Engine <a class="header-anchor" href="#📐-signal-processing-telematics-engine" aria-label="Permalink to &quot;📐 Signal Processing &amp; Telematics Engine&quot;">​</a></h2><p>GPS hardware sensors on mobile devices frequently produce velocity noise spikes, multipath signal reflections, and intermittent signal drift (especially in urban canyons or under bridges). The <code>TelematicsEngine</code> in <code>speed-core</code> applies a multi-stage mathematical pipeline before emitting speed updates.</p>',5)),a(n),e[6]||(e[6]=s('<h3 id="_1-accuracy-confidence-gating" tabindex="-1">1. Accuracy Confidence Gating <a class="header-anchor" href="#_1-accuracy-confidence-gating" aria-label="Permalink to &quot;1. Accuracy Confidence Gating&quot;">​</a></h3><p>Raw GPS fixes with an estimated horizontal accuracy greater than <strong>25.0 meters</strong> (or missing speed precision) are discarded:</p><div class="info custom-block"><p class="custom-block-title">🎯 Gating Rule</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Accept GPS Fix IF: horizontalAccuracy &lt;= 25.0 meters</span></span></code></pre></div></div><p>When a reading is rejected, the engine emits <code>SpeedData.LowAccuracy</code>, preventing erratic spikes while preserving the last valid smoothed speed.</p><hr><h3 id="_2-exponential-moving-average-ema" tabindex="-1">2. Exponential Moving Average (EMA) <a class="header-anchor" href="#_2-exponential-moving-average-ema" aria-label="Permalink to &quot;2. Exponential Moving Average (EMA)&quot;">​</a></h3><p>To eliminate abrupt needle shaking while retaining immediate responsiveness to actual vehicle acceleration, the engine applies an <strong>Exponential Moving Average</strong> with smoothing factor <strong>α = 0.3</strong>:</p><div class="info custom-block"><p class="custom-block-title">📐 Mathematical Smoothing Formula</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>S_t = (α · Y_t) + ((1 - α) · S_{t-1})</span></span></code></pre></div><ul><li><strong><code>S_t</code></strong>: Smoothed speed at timestamp $t$ (in meters/second).</li><li><strong><code>Y_t</code></strong>: Raw velocity reading from the GPS provider.</li><li><strong><code>S_{t-1}</code></strong>: Previous smoothed speed state.</li><li><strong><code>α = 0.3</code></strong>: Weighting coefficient (30% new sample, 70% historical momentum).</li></ul></div><hr><h3 id="_3-dual-schmitt-trigger-hysteresis-max-min-limits" tabindex="-1">3. Dual Schmitt Trigger Hysteresis (Max &amp; Min Limits) <a class="header-anchor" href="#_3-dual-schmitt-trigger-hysteresis-max-min-limits" aria-label="Permalink to &quot;3. Dual Schmitt Trigger Hysteresis (Max &amp; Min Limits)&quot;">​</a></h3><p>A major problem with standard telematics alerting is <strong>alarm flutter</strong> (e.g. at <code>80.1 km/h</code> the alarm fires, at <code>79.9 km/h</code> it shuts off, causing rapid flickering and annoying audio chatter).</p><p>The SDK&#39;s <code>TelematicsEngine</code> implements a <strong>Dual Schmitt Trigger Hysteresis</strong> state machine covering both <strong>Maximum Speed Limits</strong> and <strong>Minimum Speed Corridors</strong>. These dynamic limits are no longer set manually; they are now <strong>automatically fed by the selected <code>DrivingProfile</code></strong> (e.g. <code>CarHighway</code>, <code>EScooter</code>):</p>',12)),a(d),e[7]||(e[7]=s('<h4 id="a-maximum-speed-ceiling-hysteresis" tabindex="-1">A. Maximum Speed Ceiling Hysteresis <a class="header-anchor" href="#a-maximum-speed-ceiling-hysteresis" aria-label="Permalink to &quot;A. Maximum Speed Ceiling Hysteresis&quot;">​</a></h4><ul><li><strong>Trigger Threshold</strong>: Warning activates when <code>Speed &gt; MaxLimit + 1.0 km/h</code> (<code>+0.278 m/s</code>).</li><li><strong>Dismissal Threshold</strong>: Warning deactivates when <code>Speed &lt; MaxLimit - 3.0 km/h</code> (<code>-0.833 m/s</code>).</li><li><strong>Result</strong>: Sets <code>isOverLimit = true</code> in <code>SpeedData.SpeedChanged</code>.</li></ul><h4 id="b-minimum-speed-corridor-hysteresis" tabindex="-1">B. Minimum Speed Corridor Hysteresis <a class="header-anchor" href="#b-minimum-speed-corridor-hysteresis" aria-label="Permalink to &quot;B. Minimum Speed Corridor Hysteresis&quot;">​</a></h4><ul><li><strong>Startup Safety Guard (<code>hasReachedSafeSpeed</code>)</strong>: Prevents false under-speed alarms when the vehicle is stationary or starting from a parking stop until it first accelerates past <code>MinLimit + 3.0 km/h</code>.</li><li><strong>Trigger Threshold</strong>: Warning activates when driving speed drops below <code>Speed &lt; MinLimit - 1.0 km/h</code> (<code>-0.278 m/s</code>).</li><li><strong>Dismissal Threshold</strong>: Warning deactivates once speed recovers above <code>Speed &gt; MinLimit + 3.0 km/h</code> (<code>+0.833 m/s</code>).</li><li><strong>Result</strong>: Sets <code>isUnderLimit = true</code> in <code>SpeedData.SpeedChanged</code>.</li></ul><hr><h2 id="🔋-foreground-service-battery-optimization" tabindex="-1">🔋 Foreground Service &amp; Battery Optimization <a class="header-anchor" href="#🔋-foreground-service-battery-optimization" aria-label="Permalink to &quot;🔋 Foreground Service &amp; Battery Optimization&quot;">​</a></h2><p>Continuous GPS monitoring can drain mobile battery rapidly. The SDK provides advanced power-conservation strategies:</p>',7)),a(l),e[8]||(e[8]=s('<ol><li><strong><code>AutoStartManager</code> (<code>:speed-autostart</code>)</strong>: This is the new recommended strategy for battery optimization. By utilizing Google Play Services <code>IN_VEHICLE</code> transitions, it detects when a trip starts or stops using the low-power sensor hub, bypassing OEM background killers without relying on continuous GPS polling.</li><li><strong><code>ScreenStateWatcher</code></strong>: Dynamically observes display state. If the host application configures <code>updateWhileScreenOff = false</code>, the GPS hardware is immediately turned off when the screen sleeps, reducing power consumption by up to <strong>68%</strong>.</li><li><strong>Dynamic Status Bar Icons</strong>: Speed is rendered directly into the system status bar as a vector numeric drawable, allowing drivers to monitor speed without keeping the screen active.</li></ol><hr><p>👉 <strong>Next Step:</strong> Explore the <a href="/pr-preview/pr-17/guide/">Core Integration Guide</a> to initialize the SDK and collect live telematics streams.</p>',3))])}const _=c(m,[["render",h]]);export{x as __pageData,_ as default};
